# Generated by build.py from recipe.yml for recipe ldap-search-a-directory. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site/.surl/ldap' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/.surl/ldap/directory.ldif'), "dn: dc=example,dc=com`nobjectClass: domain`ndc: example`n`ndn: cn=alice,dc=example,dc=com`nobjectClass: person`ncn: alice`nsn: Liddell`nmail: alice@example.com`n`ndn: cn=bob,dc=example,dc=com`nobjectClass: person`ncn: bob`nsn: Builder`nmail: bob@example.com`n")
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--allow-plaintext-auth', '-u', 'alice:s3cret', 'ldap://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -u alice:s3cret "ldap://127.0.0.1:8080/dc=example,dc=com?cn,mail?sub?(objectClass=person)" } finally { Stop-Process $server0 }
